(()=>{const stops=[...document.querySelectorAll('[data-stop]')];const stories=[['01 / BOULDER, CO','Chemical engineering school','Sko Buffs!'],['02 / BEND, OR','The start of pharmaceutical engineering','Lonza'],['03 / LONDON, UK','Across the Atlantic','Pilot plant transfer'],['04 / SEATTLE, WA','The next chapter','My time at Invert'],['05 / PORTLAND, OR','Where I am now','Seeq']];const panel=document.querySelector('#journey-story');const list=[...document.querySelectorAll('.journey-stop')];function select(i){stops.forEach(b=>{const active=Number(b.dataset.stop)===i;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});panel.querySelector('span').textContent=stories[i][0];panel.querySelector('h3').textContent=stories[i][1];panel.querySelector('p').textContent=stories[i][2]}stops.forEach(b=>{const i=Number(b.dataset.stop);b.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')select(i)});b.addEventListener('focus',()=>select(i));b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%5;else if(e.key==='ArrowLeft')n=(i+4)%5;else if(e.key==='Home')n=0;else if(e.key==='End')n=4;else return;e.preventDefault();list[n].focus()})})})();
